-- Gate provider discovery and rank equal-distance providers by paid tier.
begin;
CREATE OR REPLACE FUNCTION public.find_nearby_drivers(_lat numeric, _lng numeric, _category text, _radius_km numeric DEFAULT 5, _limit integer DEFAULT 10)
 RETURNS TABLE(user_id uuid, distance_km numeric, rating_avg numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                  SELECT
                      x.user_id,
                          x.distance_km,
                              x.rating_avg
                                FROM (
                                    SELECT DISTINCT ON (dp.user_id)
                                          dp.user_id,
                                                dp.rating_avg,
                                                COALESCE(sp.priority_weight, 0) AS subscription_priority,
                                                      (
                                                              6371 * acos(LEAST(1.0, GREATEST(-1.0,
                                                                        cos(radians(_lat)) * cos(radians(loc.lat))
                                                                                  * cos(radians(loc.lng) - radians(_lng))
                                                                                            + sin(radians(_lat)) * sin(radians(loc.lat))
                                                                                                    )))
                                                                                                          )::numeric AS distance_km
                                                                                                              FROM public.driver_profiles dp
                                                                                                                  JOIN (
                                                                                                                        SELECT pp.user_id, pp.lat, pp.lng, pp.updated_at
                                                                                                                              FROM public.provider_presence pp

                                                                                                                                    UNION ALL

                                                                                                                                          SELECT ll.user_id, ll.lat, ll.lng, ll.updated_at
                                                                                                                                                FROM public.live_locations ll
                                                                                                                                                    ) loc ON loc.user_id = dp.user_id

                                                                                                                                                        LEFT JOIN public.user_subscriptions us
                                                                                                                    ON us.user_id=dp.user_id AND us.status='active'
                                                                                                                   AND (us.current_period_end IS NULL OR us.current_period_end>now())
                                                                                                                  LEFT JOIN public.subscription_plans sp ON sp.id=us.plan_id

                                                                                                                                                        WHERE dp.available = true
                                                                                                                                                              AND public.mamnoon_provider_subscription_active(dp.user_id)
                                                                                                                                                              AND dp.status = 'approved'

                                                                                                                                                                    AND (
                                                                                                                                                                            dp.suspended_until IS NULL
                                                                                                                                                                                    OR dp.suspended_until <= now()
                                                                                                                                                                                          )

                                                                                                                                                                                                AND (
                                                                                                                                                                                                        _category IS NULL
                                                                                                                                                                                                                OR dp.vehicle_category::text = _category
                                                                                                                                                                                                                      )

                                                                                                                                                                                                                            AND (
                                                                                                                                                                                                                                    (
                                                                                                                                                                                                                                              _category = 'large'
                                                                                                                                                                                                                                                        AND EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = dp.user_id AND ur.role = 'large_driver'::public.app_role)
                                                                                                                                                                                                                                                                                                  )
                                                                                                                                                                                                                                                                                                          OR
                                                                                                                                                                                                                                                                                                                  (
                                                                                                                                                                                                                                                                                                                            _category IS DISTINCT FROM 'large'
                                                                                                                                                                                                                                                                                                                                      AND _category IN ('economy', 'premium', 'luxury')
                                                                                                                                                                                                                                                                                                                                                AND EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = dp.user_id AND ur.role = 'driver'::public.app_role)
                                                                                                                                                                                                                                                                                                                                                                                          )
                                                                                                                                                                                                                                                                                                                                                                                                )

                                                                                                                                                                                                                                                                                                                                                                                                      AND loc.updated_at > now() - interval '5 minutes'

                                                                                                                                                                                                                                                                                                                                                                                                            AND NOT EXISTS (
                                                                                                                                                                                                                                                                                                                                                                                                                    SELECT 1
                                                                                                                                                                                                                                                                                                                                                                                                                            FROM public.service_requests sr
                                                                                                                                                                                                                                                                                                                                                                                                                                    WHERE sr.provider_id = dp.user_id
                                                                                                                                                                                                                                                                                                                                                                                                                                              AND sr.status IN ('accepted', 'in_progress')
                                                                                                                                                                                                                                                                                                                                                                                                                                                    )

                                                                                                                                                                                                                                                                                                                                                                                                                                                          AND NOT EXISTS (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  SELECT 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          FROM public.user_blocks b
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  WHERE b.user_id = dp.user_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            AND (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        b.expires_at IS NULL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    OR b.expires_at > now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ORDER BY dp.user_id, loc.updated_at DESC
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ) x

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            WHERE x.distance_km <=
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                LEAST(GREATEST(COALESCE(_radius_km, 5), 0.1), 25)

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ORDER BY
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      x.distance_km ASC,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          x.subscription_priority DESC,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          x.rating_avg DESC NULLS LAST

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            LIMIT LEAST(GREATEST(COALESCE(_limit, 10), 1), 250);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $function$
;
CREATE OR REPLACE FUNCTION public.find_nearby_provider_pins(_lat numeric, _lng numeric, _type text, _category text DEFAULT NULL::text, _service_id uuid DEFAULT NULL::uuid, _radius_km numeric DEFAULT 5, _limit integer DEFAULT 30)
 RETURNS TABLE(pin_id text, lat numeric, lng numeric, heading numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                                                                                                            SELECT
                                                                                                                                md5(pp.user_id::text),
                                                                                                                                    round(pp.lat::numeric, 3),
                                                                                                                                        round(pp.lng::numeric, 3),
                                                                                                                                            pp.heading
                                                                                                                                              FROM public.provider_presence pp
                                                                                                                                                WHERE auth.uid() IS NOT NULL
                                                                                                                                                    AND _lat BETWEEN -90 AND 90
                                                                                                                                                        AND _lng BETWEEN -180 AND 180
                                                                                                                                                            AND _type IN ('taxi', 'service')
                                                                                                                                                                AND pp.updated_at > now() - interval '5 minutes'
                                                                                                                                                                    AND public.mamnoon_provider_subscription_active(pp.user_id)
                                                                                                                                                                    AND (
                                                                                                                                                                          (_type = 'taxi' AND EXISTS (
                                                                                                                                                                                  SELECT 1
                                                                                                                                                                                          FROM public.driver_profiles dp
                                                                                                                                                                                                  WHERE dp.user_id = pp.user_id
                                                                                                                                                                                                            AND dp.available
                                                                                                                                                                                                                      AND dp.status = 'approved'
                                                                                                                                                                                                                                AND (_category IS NULL OR dp.vehicle_category::text = _category)
                                                                                                                                                                                                                                      ))
                                                                                                                                                                                                                                            OR
                                                                                                                                                                                                                                                  (_type = 'service' AND EXISTS (
                                                                                                                                                                                                                                                          SELECT 1
                                                                                                                                                                                                                                                                  FROM public.worker_profiles wp
                                                                                                                                                                                                                                                                          WHERE wp.user_id = pp.user_id
                                                                                                                                                                                                                                                                                    AND wp.available
                                                                                                                                                                                                                                                                                              AND wp.status = 'approved'
                                                                                                                                                                                                                                                                                                        AND (_service_id IS NULL OR EXISTS (
                                                                                                                                                                                                                                                                                                                    SELECT 1
                                                                                                                                                                                                                                                                                                                                FROM public.worker_services ws
                                                                                                                                                                                                                                                                                                                                            WHERE ws.worker_id = wp.user_id
                                                                                                                                                                                                                                                                                                                                                          AND ws.service_id = _service_id
                                                                                                                                                                                                                                                                                                                                                                    ))
                                                                                                                                                                                                                                                                                                                                                                          ))
                                                                                                                                                                                                                                                                                                                                                                              )
                                                                                                                                                                                                                                                                                                                                                                                  AND 6371 * acos(LEAST(1.0, GREATEST(-1.0,
                                                                                                                                                                                                                                                                                                                                                                                        cos(radians(_lat)) * cos(radians(pp.lat)) *
                                                                                                                                                                                                                                                                                                                                                                                              cos(radians(pp.lng) - radians(_lng)) +
                                                                                                                                                                                                                                                                                                                                                                                                    sin(radians(_lat)) * sin(radians(pp.lat))
                                                                                                                                                                                                                                                                                                                                                                                                        ))) <= LEAST(GREATEST(COALESCE(_radius_km, 5), 0.1), 15)
                                                                                                                                                                                                                                                                                                                                                                                                          ORDER BY pp.updated_at DESC
                                                                                                                                                                                                                                                                                                                                                                                                            LIMIT LEAST(GREATEST(COALESCE(_limit, 30), 1), 30)
                                                                                                                                                                                                                                                                                                                                                                                                            $function$
;
CREATE OR REPLACE FUNCTION public.advance_service_dispatch(_request_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
        DECLARE
          r public.service_requests%ROWTYPE;
            q public.service_dispatch_queue%ROWTYPE;
              v_radius numeric;
                v_min numeric;
                  v_count integer := 0;
                  BEGIN
                    SELECT * INTO r
                      FROM public.service_requests
                        WHERE id = _request_id
                          FOR UPDATE;

                            SELECT * INTO q
                              FROM public.service_dispatch_queue
                                WHERE request_id = _request_id
                                  FOR UPDATE;

                                    IF NOT FOUND THEN RETURN 0; END IF;
                                      IF r.type <> 'service' OR r.status NOT IN ('pending', 'searching')
                                           OR r.provider_id IS NOT NULL OR r.service_id IS NULL THEN
                                               DELETE FROM public.service_dispatch_queue WHERE request_id = _request_id;
                                                   RETURN 0;
                                                     END IF;
                                                       IF q.next_at > now() THEN RETURN 0; END IF;

                                                         IF q.stage >= 6 THEN
                                                             DELETE FROM public.service_dispatch_queue WHERE request_id = _request_id;
                                                                 INSERT INTO public.notifications(user_id, type, title, body, link, data)
                                                                     VALUES (
                                                                           r.customer_id,
                                                                                 'service_searching',
                                                                                       'انتهى البحث ضمن 25 كم',
                                                                                             'لم نعثر على فني متاح ضمن مسافة 25 كم. يمكنك إعادة المحاولة لاحقاً.',
                                                                                                   '/request/' || r.id,
                                                                                                         jsonb_build_object('request_id', r.id, 'service_id', r.service_id, 'max_radius_km', 25)
                                                                                                             );
                                                                                                                 RETURN 0;
                                                                                                                   END IF;

                                                                                                                     UPDATE public.request_offers
                                                                                                                       SET status = 'expired', responded_at = now()
                                                                                                                         WHERE request_id = _request_id
                                                                                                                             AND status = 'pending'
                                                                                                                                 AND expires_at <= now();

                                                                                                                                   v_radius := (ARRAY[2, 5, 10, 15, 20, 25]::numeric[])[q.stage + 1];
                                                                                                                                     v_min := (ARRAY[0, 2, 5, 10, 15, 20]::numeric[])[q.stage + 1];

                                                                                                                                       WITH latest_presence AS (
                                                                                                                                           SELECT DISTINCT ON (pp.user_id)
                                                                                                                                                 pp.user_id, pp.lat, pp.lng, pp.updated_at
                                                                                                                                                     FROM public.provider_presence pp
                                                                                                                                                         WHERE pp.updated_at > now() - interval '5 minutes'
                                                                                                                                                             ORDER BY pp.user_id, pp.updated_at DESC
                                                                                                                                                               ),
                                                                                                                                                                 candidates AS (
                                                                                                                                                                     SELECT
                                                                                                                                                                           wp.user_id,
                                                                                                                                                                                 (6371 * acos(LEAST(1.0, GREATEST(-1.0,
                                                                                                                                                                                         cos(radians(r.pickup_lat::double precision))
                                                                                                                                                                                                 * cos(radians(lp.lat))
                                                                                                                                                                                                         * cos(radians(lp.lng) - radians(r.pickup_lng::double precision))
                                                                                                                                                                                                                 + sin(radians(r.pickup_lat::double precision))
                                                                                                                                                                                                                         * sin(radians(lp.lat))
                                                                                                                                                                                                                               ))))::numeric AS distance_km,
                                                                                                                                                                                 COALESCE(sp.priority_weight, 0) AS subscription_priority
                                                                                                                                                                                                                                   FROM public.worker_profiles wp
                                                                                                                                                                                                                                       JOIN public.worker_services ws
                                                                                                                                                                                                                                             ON ws.worker_id = wp.user_id
                                                                                                                                                                                                                                                  AND ws.service_id = r.service_id
                                                                                                                                                                                                                                                      JOIN latest_presence lp ON lp.user_id = wp.user_id
                                                                                                                                                                                                                                                          LEFT JOIN public.user_subscriptions us
                                                                                                                        ON us.user_id=wp.user_id AND us.status='active'
                                                                                                                       AND (us.current_period_end IS NULL OR us.current_period_end>now())
                                                                                                                      LEFT JOIN public.subscription_plans sp ON sp.id=us.plan_id
                                                                                                                          WHERE wp.available = true
                                                                                                                                AND public.mamnoon_provider_subscription_active(wp.user_id)
                                                                                                                                                                                                                                                                AND wp.status = 'approved'
                                                                                                                                                                                                                                                                      AND (r.level_required IS NULL OR wp.level = r.level_required)
                                                                                                                                                                                                                                                                            AND r.pickup_lat IS NOT NULL
                                                                                                                                                                                                                                                                                  AND r.pickup_lng IS NOT NULL
                                                                                                                                                                                                                                                                                        AND NOT EXISTS (
                                                                                                                                                                                                                                                                                                SELECT 1 FROM public.service_requests active
                                                                                                                                                                                                                                                                                                        WHERE active.provider_id = wp.user_id
                                                                                                                                                                                                                                                                                                                  AND active.status IN ('accepted', 'in_progress')
                                                                                                                                                                                                                                                                                                                        )
                                                                                                                                                                                                                                                                                                                              AND NOT EXISTS (
                                                                                                                                                                                                                                                                                                                                      SELECT 1 FROM public.user_blocks b
                                                                                                                                                                                                                                                                                                                                              WHERE b.user_id = wp.user_id
                                                                                                                                                                                                                                                                                                                                                        AND (b.expires_at IS NULL OR b.expires_at > now())
                                                                                                                                                                                                                                                                                                                                                              )
                                                                                                                                                                                                                                                                                                                                                                ),
                                                                                                                                                                                                                                                                                                                                                                  inserted AS (
                                                                                                                                                                                                                                                                                                                                                                      INSERT INTO public.request_offers
                                                                                                                                                                                                                                                                                                                                                                            (request_id, provider_id, distance_km, status, sent_at, expires_at)
                                                                                                                                                                                                                                                                                                                                                                                SELECT
                                                                                                                                                                                                                                                                                                                                                                                      r.id, c.user_id, c.distance_km, 'pending', now(), now() + interval '60 seconds'
                                                                                                                                                                                                                                                                                                                                                                                          FROM candidates c
                                                                                                                                                                                                                                                                                                                                                                                              WHERE c.distance_km > v_min
                                                                                                                                                                                                                                                                                                                                                                                                    AND c.distance_km <= v_radius
                                                                                                                                                                                                                                                                                                                                                                                                          AND c.user_id <> r.customer_id
                                                                                                                                                                                                                                                                                                                                                                                                                AND NOT EXISTS (
                                                                                                                                                                                                                                                                                                                                                                                                                        SELECT 1 FROM public.request_offers existing
                                                                                                                                                                                                                                                                                                                                                                                                                                WHERE existing.request_id = r.id
                                                                                                                                                                                                                                                                                                                                                                                                                                          AND existing.provider_id = c.user_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                    AND existing.status IN ('pending', 'accepted', 'rejected')
                                                                                                                                                                                                                                                                                                                                                                                                                                                          )
                                                                                                                                                                                                                                                                                                                                                                                                                                                              ORDER BY c.distance_km ASC, c.subscription_priority DESC
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  LIMIT 10
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ON CONFLICT (request_id, provider_id) DO UPDATE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            SET status = 'pending',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      distance_km = EXCLUDED.distance_km,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                sent_at = now(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          expires_at = now() + interval '60 seconds',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    responded_at = NULL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          WHERE public.request_offers.status IN ('expired', 'cancelled')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              RETURNING id, provider_id, distance_km
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  INSERT INTO public.notifications (user_id, type, title, body, link, data)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    SELECT
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        i.provider_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'service_offer',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'طلب خدمة جديد',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'وصلك طلب ' || s.name_ar || ' بالقرب منك. لديك دقيقة للرد.',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        '/request/' || r.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'request_id', r.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'offer_id', i.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'service_id', r.service_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'service_slug', s.slug,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'service_name', s.name_ar,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'distance_km', round(i.distance_km, 2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'price_iqd', COALESCE(r.customer_price, r.price_estimate),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'pickup_text', r.pickup_text,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'work_description', r.work_description,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'workers_count', r.workers_count,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'dispatch_radius_km', v_radius
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    FROM inserted i
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      JOIN public.services s ON s.id = r.service_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        GET DIAGNOSTICS v_count = ROW_COUNT;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          UPDATE public.service_dispatch_queue
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            SET stage = q.stage + 1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  next_at = now() + interval '60 seconds'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    WHERE request_id = _request_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      RETURN v_count;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      END;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      $function$
;
commit;
